          ]
        }), headers: auth_headers(user)
      [response.status, response.parsed_body]
    end

    foreign_result = nil
    expect do
      foreign_result = post_with_links.call([own_entry.id, foreign_entry.id])
    end.to not_change(Invoice, :count).and not_change(InvoiceLineItemTimeEntry, :count)
    missing_result = post_with_links.call([own_entry.id, missing_id])

    # "A missing id and a foreign id must both give the same `not_found` error, rendered through the existing 422 path."
    expect(foreign_result.first).to eq(422)
    expect(foreign_result.last["errors"]).to include("not found")
    expect(foreign_result).to eq(missing_result)
    expect(foreign_result.last.to_s).not_to include(missing_id.to_s)
    expect([own_entry.reload.locked, foreign_entry.reload.locked]).to eq([false, false])
  end
